<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { Plus, X } from '@lucide/vue'
import { db } from '../../db'
import { useTeachingStore } from '../../stores/useTeachingStore'
import type { LessonPlan } from '../../types/schema'
import { focusModalField } from '../../utils/focusModalField'

const props = defineProps<{ editingId?: string | null }>(); const emit = defineEmits<{ close: []; saved: [LessonPlan] }>()
const teachingStore = useTeachingStore(); const saving = ref(false); const error = ref(''); const attachmentDraft = ref('')
const form = reactive({ gradeTarget: '全校通用', topicTitle: '', description: '', objectives: '', procedureText: '', attachments: [] as string[] })
function reset(plan?: LessonPlan) { Object.assign(form, plan ? { gradeTarget: plan.gradeTarget || '全校通用', topicTitle: plan.topicTitle, description: plan.description, objectives: plan.objectives, procedureText: plan.procedureText, attachments: [...plan.attachments] } : { gradeTarget: '全校通用', topicTitle: '', description: '', objectives: '', procedureText: '', attachments: [] }); error.value = '' }
function addAttachment() { const value = attachmentDraft.value.trim(); if (value && !form.attachments.includes(value)) form.attachments.push(value); attachmentDraft.value = '' }
async function save() { if (!form.topicTitle.trim() || !form.procedureText.trim()) { error.value = '请填写专题名称和教案流程。'; return }; saving.value = true; error.value = ''; const draft = { gradeTarget: '全校通用', topicTitle: form.topicTitle.trim(), description: form.description.trim(), objectives: form.objectives.trim(), procedureText: form.procedureText.trim(), attachments: [...form.attachments] }; try { let plan: LessonPlan; if (props.editingId) { await teachingStore.updateLessonPlan(props.editingId, draft); plan = (await db.lessonPlans.get(props.editingId))! } else plan = await teachingStore.addLessonPlan(draft); emit('saved', plan); emit('close') } catch (reason) { error.value = reason instanceof Error ? reason.message : '保存教案失败。' } finally { saving.value = false } }
onMounted(async () => { reset(props.editingId ? await db.lessonPlans.get(props.editingId) : undefined); const reference = teachingStore.consumeMaterialReference(); if (reference && !props.editingId) form.attachments.push(reference); await focusModalField() })
</script>

<template><Teleport to="body"><div class="fixed inset-0 z-50 bg-stone-950/30" @click.self="emit('close')"><section class="ml-auto flex h-full w-full max-w-3xl flex-col overflow-y-auto bg-white p-6 shadow-2xl"><header class="flex items-start justify-between gap-4"><div><h2 class="text-lg font-semibold text-stone-800">{{ editingId ? '编辑心理教案' : '撰写心理教案' }}</h2><p class="mt-1 text-sm text-stone-500">每份教案默认全校通用，可拖入任意年级班级的进度大盘或周课表。</p></div><button type="button" class="rounded-lg p-1.5 text-stone-400 hover:bg-stone-100" @click="emit('close')"><X :size="18" /></button></header><p v-if="error" class="mt-4 rounded-lg bg-rose-50 px-3 py-2 text-sm text-rose-700">{{ error }}</p><div class="mt-5 flex items-end gap-4"><span class="rounded-full bg-teal-50 px-3 py-2 text-sm font-medium text-teal-800">适用范围：全校通用</span><label class="min-w-0 flex-1 text-sm font-medium text-stone-700">专题名称<input v-model="form.topicTitle" class="mt-1.5 w-full rounded-lg border border-stone-200 px-3 py-2" placeholder="如：考前焦虑应对" /></label></div><label class="mt-5 block text-sm font-medium text-stone-700">课程简介<textarea v-model="form.description" rows="3" class="mt-1.5 w-full rounded-lg border border-stone-200 p-3 text-sm leading-6" placeholder="本节课面向的真实情境与核心价值。" /></label><label class="mt-5 block text-sm font-medium text-stone-700">教学目标<textarea v-model="form.objectives" rows="3" class="mt-1.5 w-full rounded-lg border border-stone-200 p-3 text-sm leading-6" placeholder="可用换行分隔知识、体验与行动目标。" /></label><label class="mt-5 block text-sm font-medium text-stone-700">教案流程 / 教学步骤<textarea v-model="form.procedureText" rows="9" class="mt-1.5 w-full rounded-lg border border-stone-200 p-3 font-mono text-sm leading-6" placeholder="一、破冰导入\n二、情境讨论\n三、体验活动\n四、课堂总结" /></label><section class="mt-5 rounded-xl border border-stone-200 p-4"><h3 class="text-sm font-semibold text-stone-800">课件与资源备注</h3><div class="mt-3 flex gap-2"><input v-model="attachmentDraft" class="min-w-0 flex-1 rounded-lg border border-stone-200 px-3 py-2 text-sm" placeholder="如：PPT 文件名、活动单说明或本地路径" @keyup.enter="addAttachment" /><button type="button" class="inline-flex items-center gap-1 rounded-lg border border-teal-200 px-3 py-2 text-sm text-teal-800 hover:bg-teal-50" @click="addAttachment"><Plus :size="15" />添加</button></div><div class="mt-3 flex flex-wrap gap-2"><span v-for="item in form.attachments" :key="item" class="inline-flex items-center gap-1 rounded-full bg-stone-100 py-1 pl-2.5 pr-1 text-xs text-stone-700">{{ item }}<button type="button" class="rounded-full px-1 text-stone-400 hover:text-rose-600" @click="form.attachments = form.attachments.filter((value) => value !== item)"><X :size="12" /></button></span></div></section><footer class="mt-6 flex justify-end gap-2 border-t border-stone-100 pt-5"><button type="button" class="rounded-lg px-4 py-2 text-sm text-stone-600 hover:bg-stone-100" @click="emit('close')">取消</button><button type="button" :disabled="saving" class="rounded-lg bg-teal-700 px-4 py-2 text-sm font-semibold text-white disabled:opacity-50" @click="save">{{ saving ? '保存中…' : '保存教案' }}</button></footer></section></div></Teleport></template>
